/* port.h: the ported monsters as the core sees them (module/port.c).
 * port_monsters[] is generated by module/build.py from allocations.toml (IDs) and monsters/<name>/package.toml (C
 * symbol prefix), in registry order. Every registered monster's data file nativeNX/mh4uport/<name>.bin always ships
 * (tables + text, tools/portdata.py); the monster counts as INSTALLED when its assets are present (its monster arc).
 * Gear / items / Notes / name come from the data file whatever is installed (IDs never move); quests, spawning and
 * quest-time hooks need the monster installed. */
#pragma once
#include <stdint.h>
#include "alloc.h"

#define PORT_N ((int)PORT_MONSTER_COUNT)
#define PORT_LANGS 5          /* eng fre ger ita spa: text order in every data section */
#define PORT_QUESTS 12        /* quests per entry (module/build.py QUESTS_PER_ENTRY) */

struct port_monster {
    const char *name;                     /* data file + log name */
    uint16_t em_id, index, donor_index, standin_id;   /* standin 0 = none */
    uint16_t save_index, save_id, name_entry, notes_entry;   /* notes_entry 0 = none (a companion) */
    uint32_t quests[PORT_QUESTS], quest_slots[PORT_QUESTS];   /* 0 = none; quests[0] unlocks the Notes entry; slots
                                                                 = the quest list entries renamed (module/quest.c) */
    void (*register_class)(void);         /* 0 = a GU class runs it (package.toml gu_class), or an earlier entry
                                             registered the same class */
    int owner;                            /* a companion (allocations.toml companion_of): its owner's port index;
                                             -1 = a monster. Companions spawn in their owner's quests */
    uint8_t stage_from, stage_folder;     /* allocations.toml stage_alias: while its quests run, GU stage stage_from
                                             loads folder m<stage_folder> (module/stage_alias.c); 0 = none */
    uint8_t stage_hold;                   /* package.toml [stage] hold_kobj_areas: area bit mask */
    uint32_t stage_kinds;                 /* package.toml [stage] kinds: arc path kinds redirected, bit kind - 48 */
    uint8_t map_n;                        /* package.toml [stage] maprec: area map records {4U k, x, y} per area */
    float map_k[4];
    int16_t map_x[4], map_y[4];
    float whole_k;                        /* package.toml [stage] wholemap_k: whole-map record scale */
    float size[4];                        /* package.toml [size]: 4U base size (cm), mini / silver / gold ratios
                                             (0 = no crowns); base 0 = none (module/main.c size_data) */
    uint8_t quest_append;                 /* allocations.toml quest_append: its quests are new quest list entries
                                             after GU's (module/quest.c quest_group_append), no quest_slots */
    uint16_t standin_alt, standin_alt_mask;   /* allocations.toml standin_alt = [ID, quest...]: in those quests
                                             (bit k = quests[k]) its boss record names this stand-in instead, so
                                             standin_id can be a real GU boss next to it; 0 = none */
    uint16_t stage_name;                  /* allocations.toml [monster.append] stage_name: questMessage index of the
                                             alias's name (its TXTA string), shown for its quests on stage_from
                                             (module/stage_alias.c); 0 = GU's name */
    uint8_t lease;                        /* allocations.toml save = "lease": no fixed save slot (save_index /
                                             save_id 0), it borrows one per quest and its numbers go to the store
                                             (module/save.c) */
};
#define PORT_OWNER(m) (port_monsters[m].owner >= 0 ? port_monsters[m].owner : (m))
extern const struct port_monster port_monsters[];   /* out/port_monsters.c */
extern uint32_t port_manifests[][51];               /* registry file manifests (reg_files[index] points here) */

/* data file: 1 = loaded and valid (loads on the first call, from any thread) */
int port_data(int m);
void port_load_all(void);
/* the nth section with this tag (several may share one), 0 if none; *size = its size */
const uint8_t *port_section(int m, const char *tag, int nth, uint32_t *size);
#define PORT_U32(sec, off) (*(const uint32_t *)((sec) + (off)))
#define PORT_STR(sec, off) ((const char *)(sec) + PORT_U32(sec, off))
/* 1 = its assets are installed (monster arc present, and its map's stage arc when it has a stage alias) */
int port_installed(int m);
/* 1 = quests[k]'s loose questData file is present (the quest builders write it with the quest arc) */
int port_quest_present(int m, int k);

int port_by_em(uint32_t em_id);           /* -1 = none */
int port_by_index(uint32_t index);
/* quests: the accepted / running quest ID (0 = none); the monster owning a quest (and its quest number 0 / 1) */
uint32_t port_quest_id(void);
int port_quest_owner(uint32_t quest_id, int *which);
int port_running_quest(int *which);       /* owner of the current quest if installed, else -1 */
/* the stand-in ID monster m's quests[k] name (standin_alt where its mask has bit k, else standin_id; 0 = none) */
uint16_t port_standin(int m, int k);

void notes_data_loaded(int m);            /* notes.c: the monster's Notes entry, after its data loaded */

/* save.c: the mod's save store and per-quest leases of the save slots 105..111 (notes/save-store.md) */
int port_lease(int m);                    /* 1 = no fixed save slot (save = "lease", or the TEST_LEASE build's) */
uint32_t save_slot_tally(int m, uint8_t *quest);   /* the slot index monster m's quest tally counts in */
int save_slot_user(uint32_t id);          /* the monster a slot ID (0x1064..0x106a) stands for, -1 = none */
int save_lessee_of_index(uint32_t idx);   /* the lessee slot index idx stands for, -1 = none */
void size_slot_dress(uint32_t slot, int m);   /* main.c: the slot's size record shows m's (-1 = as built) */
int save_loaded_c(uint32_t *regs), save_writing_c(uint32_t *regs);   /* hooks, also run by tools/test_save.c */
int stats_hunted_c(uint32_t *regs), save_hunts_c(uint32_t *regs), save_hunts_id_c(uint32_t *regs),
    save_captures_id_c(uint32_t *regs), save_size_read_c(uint32_t *regs), save_add_hunts_c(uint32_t *regs),
    save_add_captures_c(uint32_t *regs), save_size_max_c(uint32_t *regs), save_size_min_c(uint32_t *regs),
    size_lookup_c(uint32_t *regs);

/* bgm.c: a monster's own battle theme (2 sequences of its own STQR), registered from its class registration */
struct port_bgm {
    const char *port, *name;              /* log prefix and monster name ("gogport", "em089") */
    uint8_t em_types[4];                  /* em type bytes (em ID & 0xff) of its boss entries / units; 0 = unused */
    uint8_t standins[2];                  /* stand-in em types answered while quest() holds; 0 = unused */
    int (*quest)(void);                   /* nonzero while one of its quests runs */
    uint32_t stqr_file;                   /* file ID of its STQR (its arc) */
    uint32_t ids[2];                      /* phase 1 / phase 2 sequence ids (allocations.toml bgm_ids) */
    int (*phase2)(void *unit);            /* nonzero = phase 2; unit = its unit found by the boss entry, or 0 */
};
void port_bgm_register(const struct port_bgm *b);
